            {/* Purpose & Scope */}



1. Purpose & Operational Scope


                {generatedSOP.purpose}



            {/* Hazards Identification */}



2. Hazard Identification & Risk Assessment (HIRA)


                {generatedSOP.hazards.map((h, i) => (




                      {h.category}

{h.description}


                      {h.riskLevel} Risk


