import { useEffect, useState, useRef } from 'react';
import { useNellyStore } from '../../store/nellyStore';
import { speak, stopSpeaking } from '../../utils/speech';

interface TourManagerProps {
    setActiveTab: (tab: string) => void;
}

export const TourManager = ({ setActiveTab }: TourManagerProps) => {
    const { isTourActive, setTourActive, setSpeaking, setMood, setGuidance, language } = useNellyStore();
    const [step, setStep] = useState(0);
    const timeoutRef = useRef<ReturnType | null>(null);

    const tourSteps = [
        {
            tab: 'dashboard',
            text: "Welcome to ErgoSafe Reborn. This is your central command center. Here you can monitor your safety score and quick stats at a glance.",
            mood: 'happy' as const,
        },
        {
            tab: 'assessment',
            text: "Let's check your workspace. My Self-Assessment module uses AI to guide you through ergonomic corrections for your chair and desk.",
            mood: 'neutral' as const,
        },
        {
            tab: 'risks',
            text: "Prevention is key. In the Risky Behaviors section, we identify common hazards like slouching or poor lighting before they cause injury.",
            mood: 'concerned' as const,
        },
        {
            tab: 'training',
            text: "Actionable health. Our 3D Interactive Training modules feature guided exercises to keep you moving and pain-free.",
            mood: 'happy' as const,
        },
        {
            tab: 'admin',
            text: "For management, the HR Dashboard provides real-time compliance tracking and risk analysis across your entire organization.",
            mood: 'neutral' as const,
        },
        {
            tab: 'dashboard',
            // TODO(legal-verify): removed fabricated '200% increase in workforce efficiency'
            text: "Proactive ergonomic management fosters a healthier, safer workplace. Request an enterprise walkthrough to support your team.",
            mood: 'happy' as const,
        }
    ];

    useEffect(() => {
        if (!isTourActive) {
            setStep(0);
            stopSpeaking();
            if (timeoutRef.current) clearTimeout(timeoutRef.current);
            return;
        }

        const runStep = (index: number) => {
            if (index >= tourSteps.length) {
                setTourActive(false);
                setGuidance(null);
                setSpeaking(false);
                return;
            }

            const current = tourSteps[index];

            // 1. Visual State
            setActiveTab(current.tab);
            setMood(current.mood);
            setSpeaking(true);
            setGuidance(current.text);

            // 2. Audio Logic
            /* 
               We use a safety timeout of 15 seconds. 
               If speech finishes earlier, onEnd triggers the next step and clears timeout.
               If speech fails/hangs, timeout forces next step.
            */
            if (timeoutRef.current) clearTimeout(timeoutRef.current);

            const nextStep = () => {
                setSpeaking(false);
                // Simple delay between steps for better pacing
                if (timeoutRef.current) clearTimeout(timeoutRef.current);
                timeoutRef.current = setTimeout(() => {
                    // Update internal state to trigger next effect or recursive call?
                    // Better to just change the step state to trigger re-render processing?
                    // Actually, the recursively called function in useEffect is dangerous if not careful.
                    // Let's use the setStep state to drive this.
                    setStep(s => s + 1);
                }, 1000);
            };

            // Set safety fallback
            timeoutRef.current = setTimeout(nextStep, 15000);

            speak(current.text, language, nextStep);
        };

        runStep(step);

        return () => {
            // Cleanup on unmount or step change is tricky with the recursive logic above.
            // Actually, useEffect will re-run when `step` changes.
            // So we just need to ignore the 'runStep' internal definition and rely on effect.
        };
    }, [isTourActive, step]);
    // Removed other deps to avoid re-triggering mid-speech if visual props change, 
    // although they shouldn't. The critical driver is `step` and `isTourActive`.

    return null;
};

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { BrainCircuit, Target, ShieldAlert, ShieldCheck } from 'lucide-react';
import { useFatigueStore } from '../../logic/Fatigue-Check/fatigueStore';
import { useNellyStore } from '../../store/nellyStore';
import { HandshakeCardHeader } from '../common/HandshakeCardHeader';

interface CognitiveHandshakeProps {
    isInlinePage?: boolean;
}

export const CognitiveHandshake = ({ isInlinePage = false }: CognitiveHandshakeProps) => {
    const { cognitiveHandshakePassed, showCognitiveHandshake, setShowCognitiveHandshake, passCognitiveHandshake, failCognitiveHandshake, warnCognitiveHandshake, supervisorOverride } = useFatigueStore();
    const { setGuidance, setSpeaking, setMood } = useNellyStore();

    // Game State
    const [targetsHit, setTargetsHit] = useState(0);
    const [targetPos, setTargetPos] = useState({ x: 50, y: 50 });
    const [reactionTimes, setReactionTimes] = useState([]);
    const [lastTargetTime, setLastTargetTime] = useState(Date.now());
    const [gameCompleted, setGameCompleted] = useState(false);
    const [showKaizenBonus, setShowKaizenBonus] = useState(false);
    const [showLiabilityWarning, setShowLiabilityWarning] = useState(false);
    const [handshakeResult, setHandshakeResult] = useState<'pass' | 'warning' | 'fail' | null>(null);
    const [measuredAvgReaction, setMeasuredAvgReaction] = useState(null);

    const TOTAL_TARGETS = 5;

    const resetTest = () => {
        setTargetsHit(0);
        setReactionTimes([]);
        setGameCompleted(false);
        setHandshakeResult(null);
        setMeasuredAvgReaction(null);
        setShowLiabilityWarning(false);
        setLastTargetTime(Date.now());
        setTargetPos({
            x: Math.floor(Math.random() * 80) + 10,
            y: Math.floor(Math.random() * 70) + 15
        });
    };

    const handleTargetClick = () => {
        const timeToClick = Date.now() - lastTargetTime;
        setReactionTimes(prev => [...prev, timeToClick]);

        if (targetsHit + 1 >= TOTAL_TARGETS) {
            finishGame([...reactionTimes, timeToClick]);
        } else {
            setTargetsHit(prev => prev + 1);
            setTargetPos({
                x: Math.floor(Math.random() * 80) + 10,
                y: Math.floor(Math.random() * 70) + 15
            });
            setLastTargetTime(Date.now());
        }
    };

    const finishGame = (finalTimes: number[]) => {
        setShowCognitiveHandshake(false);
        setGameCompleted(true);

        const avgReaction = finalTimes.reduce((a, b) => a + b, 0) / finalTimes.length;
        setMeasuredAvgReaction(avgReaction);

        // Calculate Standard Deviation (Variance Analysis)
        const squareDiffs = finalTimes.map(time => Math.pow(time - avgReaction, 2));
        const avgSquareDiff = squareDiffs.reduce((a, b) => a + b, 0) / squareDiffs.length;
        const stdDev = Math.sqrt(avgSquareDiff);
        const variancePercentage = (stdDev / avgReaction) * 100;

        // Connect to Memory Vault
        const { reactionMemory, addReactionMemory, evaluateDriverFatigue, drivingHours } = useFatigueStore.getState();
        let isFatigued = false;
        let historicalBaseline = 0;

        if (reactionMemory.length > 0) {
            const historicalBaselineValue = reactionMemory.reduce((a, b) => a + b, 0) / reactionMemory.length;
            historicalBaseline = historicalBaselineValue;

            isFatigued = avgReaction > (historicalBaselineValue * 1.20) || 
                         variancePercentage > 35 ||
                         avgReaction > 1000;
        } else {
            isFatigued = avgReaction > 1000; 
        }

        addReactionMemory(avgReaction);

        // Sync with Prizm Driver Shift Fatigue score
        const dropPct = Math.round(Math.min(50, Math.max(0, (variancePercentage / 2))));
        evaluateDriverFatigue(drivingHours, dropPct);

        setSpeaking(true);
        if (isFatigued) {
            failCognitiveHandshake();
            setHandshakeResult('fail');
            setShowLiabilityWarning(true);
            setMood('concerned');

            const reason = variancePercentage > 35 ? "High Cognitive Variance" : "Latency Threshold Breach";
            setGuidance(`PROTOCOL ALERT: ${reason} detected. Handshake failed with ${Math.round(variancePercentage)}% variance. Status logged as High Fatigue.`);
        } else if (historicalBaseline && avgReaction < (historicalBaseline * 1.10) && avgReaction < 700) {
            passCognitiveHandshake();
            setHandshakeResult('pass');
            setShowKaizenBonus(true);
            setMood('happy');
            setGuidance("KAIZEN BONUS: Optimal latency (<700ms) and low variance detected. Handshake cleared. Prizm Driver Fatigue Telemetry updated.");
            setTimeout(() => setShowKaizenBonus(false), 1200);
        } else if (historicalBaseline && (avgReaction >= (historicalBaseline * 1.15) || variancePercentage > 25)) {
            warnCognitiveHandshake();
            setHandshakeResult('warning');
            setMood('concerned');
            setGuidance(`MUDA DETECTED: Variance is ${Math.round(variancePercentage)}% from baseline. Your cognitive consistency is slipping. Consider a professional reset.`);
        } else {
            passCognitiveHandshake();
            setHandshakeResult('pass');
            setMood('happy');
            setGuidance("Cognitive Handshake passed! Prizm Shift & Ergonomic Latency status set to NOMINAL.");
        }

        setTimeout(() => setSpeaking(false), 3000);
    };

    // If rendered as an inline page, display full interactive page UI
    if (isInlinePage) {
        return (







                            Cognitive Latency & Shift Telemetry



                                Ergonomics Cognitive Handshake



                                Interactive dot-click latency test. Calibrate reaction times to pass the Mandatory Cognitive Handshake and evaluate fatigue.




                            RE-CALIBRATE HANDSHAKE



                    {/* Interactive Dot-Click Test Area */}







                                Dot-Click Latency Calibrator



                                {Array.from({ length: TOTAL_TARGETS }).map((_, i) => (
                                    <div key={i} className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${i < targetsHit ? 'bg-[#2dd4bf] shadow-[0_0_10px_rgba(45,212,191,0.8)]' : 'bg-white/10'}`} />
                                ))}





                            {!gameCompleted ? (



                            ) : (








                                        {handshakeResult === 'fail'
                                            ? 'HANDSHAKE FAILED — HIGH FATIGUE DETECTED'
                                            : handshakeResult === 'warning'
                                            ? 'HANDSHAKE WARNING — MODERATE FATIGUE'
                                            : (gameCompleted && handshakeResult === 'pass' && cognitiveHandshakePassed)
                                            ? 'HANDSHAKE VERIFIED & PASSED'
                                            : 'HANDSHAKE PENDING'}



                                        {handshakeResult === 'fail'
