import { useState, useEffect } from 'react';
import { useNellyStore } from '../../store/nellyStore';
import { useFatigueStore } from '../../logic/Fatigue-Check/fatigueStore';
import { useAgentLog } from '../../store/agentLogStore';
import { translations, Language } from '../../utils/translations';
import { speak } from '../../utils/speech';
import { Globe, Send, MessageSquare, PlayCircle, ShieldCheck } from 'lucide-react';
import { ReasoningLog } from '../../components/agent/ReasoningLog';

export const NellyCoachPage = () => {
    const { 
        isSpeaking, 
        setSpeaking, 
        language, 
        setLanguage, 
        setGuidance 
    } = useNellyStore();
    const { addLog, logs } = useAgentLog();
    const { fatigueLevel } = useFatigueStore();
    const [userInput, setUserInput] = useState('');

    const activeLang: Language = (language && translations[language]) ? language : 'en';

    const handleSend = () => {
        if (!userInput.trim()) return;

        const lowCase = userInput.toLowerCase();
        addLog('User', userInput);

        const emergencyKeywords = ['severe pain', 'fainting', 'injury', 'accident'];
        const firstAidKeywords = ['first aid', 'first_aid', 'basic_first_aid_training_nsh', 'bleeding'];
        const symptomKeywords = ['tingling', 'numbness', 'pins and needles', 'sharp pain', 'burning'];
        const isNeckPain = lowCase.includes('neck pain') || lowCase.includes('cervical') || lowCase.includes('neck');

        const isEmerg = emergencyKeywords.some(word => lowCase.includes(word));
        const isFirstAid = firstAidKeywords.some(word => lowCase.includes(word));
        const isSymptom = symptomKeywords.some(word => lowCase.includes(word));

        if (isEmerg) {
            setSpeaking(true);
            const response = translations[activeLang]?.high_discomfort_disclaimer || translations['en'].high_discomfort_disclaimer;
            setGuidance(response);
            addLog('Nelly', response);
            speak(response, activeLang, () => setSpeaking(false));
        } else if (isFirstAid) {
            const response = translations[activeLang]?.first_aid || translations['en'].first_aid;
            setGuidance(response);
            addLog('Nelly', response);
            setSpeaking(true);
            speak(response, activeLang, () => setSpeaking(false));
        } else if (isNeckPain) {
            setSpeaking(true);
            const response = "WARNING: Cervical load or neck pain detected. I have triggered the Cervical Orthopedic Micro-Circuit. Please perform the Tier 2 micro-stretch intervention immediately to relieve strain.";
            setGuidance(response);
            addLog('Nelly', response);
            speak(response, activeLang, () => setSpeaking(false));
        } else if (isSymptom) {
            setSpeaking(true);
            const response = "WARNING: Nerve compression warning. Prolonged static posture causes spinal and wrist load. Action: Stand up and roll your shoulders now.";
            setGuidance(response);
            addLog('Nelly', response);
            speak(response, activeLang, () => setSpeaking(false));
        } else {
            setSpeaking(true);
            addLog('Nelly', "Analyzing telemetry for ergonomic coaching response...");

            setTimeout(() => {
                const response = translations[activeLang]?.nelly_intro || translations['en'].nelly_intro;
                setGuidance(response);
                addLog('Nelly', response);
                speak(response, activeLang, () => setSpeaking(false));
            }, 1000);
        }
        setUserInput('');
    };

    const triggerSafetyTour = () => {
        const response = "Safety Tour initialized: We will verify your workspace angles, screen distance, and perform a quick cervical strain pre-check.";
        addLog('Nelly', response);
        speak(response, activeLang);
    };

    const triggerStewardship = () => {
        const response = translations[activeLang]?.compliance_check || translations['en'].compliance_check;
        addLog('Nelly', response);
        speak(response, activeLang);
    };

    return (




                Digital Companion

NELLY AI SAFETY COACH

Direct interface for ergonomic guidance, pre-qualification checks, and multilingual voice assistance.




                {/* Chat Area */}





                    {/* Chat Header */}






                            Nelly Voice Stream





                             setLanguage(e.target.value as Language)}
                                className="bg-transparent text-xs font-bold text-gray-400 focus:outline-none cursor-pointer"
                            >
                                English (ZA)
                                isiZulu
                                isiXhosa
                                KiSwahili
                                Mandarin (ZH)
                                Deutsch
                                Sesotho




                    {/* Messages */}






                                "{translations[activeLang]?.nelly_intro || translations['en'].nelly_intro}"



                        {logs.slice(-10).map((log) => (




                                    {log.agent}

{log.message}


                        ))}


                    {/* Controls & Input */}





                                Safety Tour


                                Pre-Qual Check





                             setUserInput(e.target.value)}
                                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                                placeholder="Report symptom or ask for advice (e.g. 'neck pain')..."
                                className="flex-1 bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-xs focus:outline-none focus:border-ohs-orange/50 text-white"
                            />







                {/* Info Sidebar */}








                             Voice Configuration



                            Nelly is configured with a high-fidelity en-ZA Gauteng English voice model as the default. Multilingual routing is fully active for South African regional languages.





    );
};

import { useState, useEffect } from 'react';
import { Camera, CameraOff, ShieldAlert, Activity, Timer } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { trackEvent } from '../../utils/telemetry';

export const PostureTelemetry = () => {
    const [isCameraActive, setIsCameraActive] = useState(false);
    const [postureState, setPostureState] = useState<'optimal' | 'warning' | 'danger'>('optimal');
    const [flexAngle, setFlexAngle] = useState(12); // degrees
    const [trapLoad, setTrapLoad] = useState(4.2); // kg
    const [activeIntervention, setActiveIntervention] = useState<'eye-reset' | 'micro-stretch' | 'active-recovery' | null>(null);
    const [timeLeft, setTimeLeft] = useState(0);

    // Dynamic angles and loads based on posture state
    useEffect(() => {
        if (postureState === 'optimal') {
            setFlexAngle(12);
            setTrapLoad(4.2);
        } else if (postureState === 'warning') {
            setFlexAngle(32);
            setTrapLoad(12.8);
        } else {
            setFlexAngle(58);
            setTrapLoad(24.5);
        }
    }, [postureState]);

    // Timer logic for interventions
    useEffect(() => {
        if (timeLeft <= 0) {
            return;
        }
        const timer = setTimeout(() => {
            setTimeLeft(prev => prev - 1);
        }, 1000);
        return () => clearTimeout(timer);
    }, [timeLeft]);

    const triggerIntervention = (tier: 'eye-reset' | 'micro-stretch' | 'active-recovery') => {
        trackEvent('INTERVENTION_TRIGGERED', { tier });
        setActiveIntervention(tier);
        if (tier === 'eye-reset') setTimeLeft(30);
        else if (tier === 'micro-stretch') setTimeLeft(120);
        else setTimeLeft(300);
    };

    const triggerNeckPainCircuit = () => {
        trackEvent('NECK_PAIN_REPORTED', { severity: 'cervical' });
        // Auto trigger micro-stretch (Tier 2) immediately for cervical relief
        triggerIntervention('micro-stretch');
    };

    return (


            {/* Ambient glows */}














MediaPipe 3D Posture Telemetry

Client-Side Edge-AI Skeletal Mapping



                 setIsCameraActive(!isCameraActive)}
                    className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wider transition-all flex items-center gap-2 ${
                        isCameraActive
                            ? 'bg-red-500/20 text-red-400 border border-red-500/30'
                            : 'bg-ohs-orange hover:bg-yellow-400 text-ohs-navy shadow-lg shadow-ohs-orange/20'
                    }`}
                >
                    {isCameraActive ? (
                        <>
                             Disable Camera
                        </>
                    ) : (
                        <>
                             Enable Camera
                        </>
                    )}





                {/* 3D Skeletal Feed Area */}


                    {isCameraActive ? (


                            {/* Simulated webcam stream background */}


                            {/* Green Skeletal Overlay lines */}

                                {/* Joints */}
                                 {/* Head */}
                                 {/* Cervical C1 */}
                                 {/* Spine Thoracic */}
                                 {/* Left Shoulder */}
                                 {/* Right Shoulder */}

                                {/* Bones/Connections */}



                                {/* Dynamic cervical deflection line based on posture */}


                                {/* Trapezius Load Vector */}





                                live skeletal wireframe active


                    ) : (




Webcam mapping is off. Turn on camera to initialize real-time edge posture telemetry.

                    )}


                {/* Telemetry Metrics & Intervention Trigger controls */}








                                Cervical Flex

{flexAngle}°
                                Deg. from vertical axis




                                Trapezius Load

{trapLoad} kg
                                Equivalent force



                        {/* Telemetry Simulation Controllers */}


                            Calibrate Telemetry State


                                {(['optimal', 'warning', 'danger'] as const).map((s) => (
                                     setPostureState(s)}
                                        className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-wider transition-all border ${
                                            postureState === s
                                                ? s === 'danger' ? 'bg-red-500 border-red-500 text-white' 
                                                  : s === 'warning' ? 'bg-yellow-500 border-yellow-500 text-ohs-navy'
                                                  : 'bg-emerald-500 border-emerald-500 text-white'
                                                : 'bg-black/40 border-white/15 text-gray-400 hover:bg-white/5'
                                        }`}
                                    >
                                        {s}

                                ))}



                        {/* Orthopedic pain triggers */}





                                Workspace Diagnostic



                                If you are experiencing stiffness or neck fatigue, report to activate the orthopedic relief circuit.


                                Report Active Neck Pain




                    {/* Zero-Bypass Interventions Triggers */}


                        Micro-Break Interventions


                             triggerIntervention('eye-reset')}
                                className="bg-white/5 border border-white/10 hover:bg-white/10 text-white py-2.5 rounded-xl font-bold text-[9px] uppercase tracking-wider transition-all text-center"
                            >
                                30s Eye Reset

                             triggerIntervention('micro-stretch')}
                                className="bg-white/5 border border-white/10 hover:bg-white/10 text-white py-2.5 rounded-xl font-bold text-[9px] uppercase tracking-wider transition-all text-center"
                            >
                                2m Stretch

                             triggerIntervention('active-recovery')}
                                className="bg-white/5 border border-white/10 hover:bg-white/10 text-white py-2.5 rounded-xl font-bold text-[9px] uppercase tracking-wider transition-all text-center"
                            >
                                5m Recovery






            {/* Zero-Bypass Intervention Full-Screen Overlay */}

                {activeIntervention && (










                                {activeIntervention === 'eye-reset' ? 'Tier 1: Eye Reset Break' :
                                 activeIntervention === 'micro-stretch' ? 'Tier 2: Orthopedic Micro-Stretch' :
                                 'Tier 3: Active Posture Recovery'}


                                Zero-Bypass OHS Mandated Intervention






                                    {activeIntervention === 'eye-reset' ? 'Focus on an object 20 feet away for 20 seconds. Relax the ciliary muscles of the eyes.' :
                                     activeIntervention === 'micro-stretch' ? 'Stand up, roll your shoulders backward, and tilt your head laterally left-to-right to relieve C1-C7 cervical load.' :
                                     'Stand up completely, step away from the display screen, walk for 5 minutes, and take deep diaphragmatic breaths.'}







                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}


                                 {
                                        if (timeLeft <= 0) {
                                            setActiveIntervention(null);
                                        } else {
                                            alert("This is a Zero-Bypass safety stretch. Please complete the countdown.");
                                        }
                                    }}
                                    disabled={timeLeft > 0}
                                    className={`px-8 py-3.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
