                                            ? 'bg-ohs-orange hover:bg-yellow-400 text-ohs-navy shadow-lg shadow-ohs-orange/20 cursor-pointer'
                                            : 'bg-white/5 border border-white/10 text-gray-500 cursor-not-allowed'
                                    }`}
                                >
