}

// Shared material instantiations moved outside render cycle to prevent GC thrashing and frame drops
const botMaterial = new THREE.MeshStandardMaterial({
    color: "#F9A825",
    roughness: 0.3,
    metalness: 0.8
});
const botJointMaterial = new THREE.MeshStandardMaterial({
    color: "#003D5C",
    roughness: 0.5,
    metalness: 0.5
});

const ErgoBotCanvas = lazy(() => import('./ErgoBotCanvas'));

export const TrainingModule = ({ id, title, description, duration, onClose }: TrainingModuleProps) => {
    const [isPlaying, setIsPlaying] = useState(false);
    const [voiceEnabled, setVoiceEnabled] = useState(true);
    const [currentStepIdx, setCurrentStepIdx] = useState(0);
    const { completeModule, language, setLanguage } = useNellyStore();

    useEffect(() => {
        document.body.style.overflow = 'hidden';
        return () => {
            document.body.style.overflow = '';
        };
    }, []);


    // Get the course from our stabilized master data registry
    const course = FRESH_OHS_PROJECT_REGISTRY[id];
    const steps = course ? course.steps : [];
    const currentStep = steps[currentStepIdx];

    const speakCurrentInstruction = (step = currentStep) => {
        if (!step) return;
        const stepText = step[language] || step['en'];
        speak(`Step ${step.step}: ${step.title}. ${stepText}`, language);
    };

    useEffect(() => {
        return () => {
            stopSpeaking();
        };
    }, [id]);

    const handleTogglePlay = () => {
        const nextIsPlaying = !isPlaying;
        setIsPlaying(nextIsPlaying);
        if (nextIsPlaying && voiceEnabled) {
            speakCurrentInstruction();
        } else if (!nextIsPlaying) {
            stopSpeaking();
        }
    };

    const handleNext = () => {
        if (currentStepIdx < steps.length - 1) {
            const nextStepIdx = currentStepIdx + 1;
            setCurrentStepIdx(nextStepIdx);
            if (voiceEnabled) {
                speakCurrentInstruction(steps[nextStepIdx]);
            }
        } else {
            completeModule(id);
            onClose();
        }
    };

    const handlePrev = () => {
        if (currentStepIdx > 0) {
            setCurrentStepIdx(currentStepIdx - 1);
        }
    };

    return (


                {/* Close Button */}




                {/* Left: 3D Visualization */}




                        <Suspense fallback={
Loading 3D Visualizer...}>










                                {duration} Session



                                OHS ACT SEC 8




                    {/* Decorative elements */}




                {/* Right: Instructions & Steps */}




                        {/* Header with Title and Language Selector */}





                                    {course?.courseId || 'ST-OHS-001'} Statutory Module


{title}


                            {/* Multilingual Selector */}



                                Lang:
                                 setLanguage(e.target.value as Language)}
                                    className="bg-transparent text-xs font-bold text-white focus:outline-none cursor-pointer uppercase"
                                >
                                    {Object.entries(VOICEOVER_ACCENT_MAP).map(([code, config]) => (

                                            {config.displayName} ({config.regionalAccent})

                                    ))}




                        {/* Step Display Area */}
                        {currentStep && (





                                        STEP {currentStep.step} OF {steps.length}





                                    {currentStep.title}






                                        "{currentStep[language] || currentStep['en']}"



                        )}

                        {/* Linear Step Indicators */}


                            {steps.map((s, idx) => (
                                 setCurrentStepIdx(idx)}
                                    className={`h-1.5 rounded-full transition-all flex-1 min-w-[12px] ${
                                        idx === currentStepIdx 
                                            ? 'bg-ohs-orange shadow-[0_0_8px_#F9A825]' 
                                            : idx < currentStepIdx 
                                                ? 'bg-ohs-green' 
                                                : 'bg-white/10'
                                    }`}
                                />
                            ))}



                    {/* Controls Footer */}


                        {/* Audio Guidance Feedback */}




                                {voiceEnabled ?  : }


                                    Nelly Active TTS Guidance
                                    Automatic voice playback for localized pipelines


                             {
                                    const nextVoiceEnabled = !voiceEnabled;
                                    setVoiceEnabled(nextVoiceEnabled);
                                    if (nextVoiceEnabled) {
                                        speakCurrentInstruction();
                                    } else {
                                        stopSpeaking();
                                    }
                                }}
                                className={`w-12 h-6 rounded-full relative flex items-center transition-all p-0.5 shrink-0 ${voiceEnabled ? 'bg-ohs-green justify-end' : 'bg-white/20 justify-start'}`}
                            >





                        {/* Navigation Actions */}









                                    {isPlaying ? (
                                        <>

                                            STOP GUIDANCE
                                        </>
                                    ) : (
                                        <>

                                            VOICE INSTRUCTION
                                        </>
                                    )}




                                {currentStepIdx === steps.length - 1 ? (
                                    <>

                                        COMPLETE SESSION
                                    </>
                                ) : (
                                    <>
                                        NEXT INSTRUCTION

                                    </>
                                )}






    );
};

