            description: lib.description,
            duration: lib.duration,
            steps: lib.sections.map(s => `[${s.format.toUpperCase()}] ${s.title}`),
            onComplete: () => completeModule(lib.id)
        };
        setSelectedModule(mod);
    };

    return (


