            { id: 'iso-9001',  title: lang === 'zu' ? 'ISO 9001:2015 – Ukuphathwa Kwekhwalithi' : lang === 'xh' ? 'ISO 9001:2015 – UkuLawulwa kweKhwalithi' : lang === 'st' ? 'ISO 9001:2015 – Tsamaiso ea Boleng' : lang === 'sw' ? 'ISO 9001:2015 – Usimamizi wa Ubora' : lang === 'zh' ? 'ISO 9001:2015 – 质量管理' : lang === 'de' ? 'ISO 9001:2015 – Qualitätsmanagement' : 'ISO 9001:2015 – Quality Management (Voluntary)',       text: this.getComplianceVector('ISO', '9001-2015', lang)  },
            { id: 'iso-14001', title: lang === 'zu' ? 'ISO 14001:2015 – Ukuphathwa Kwezemvelo' : lang === 'xh' ? 'ISO 14001:2015 – UkuLawulwa kokusiNgqongileyo' : lang === 'st' ? 'ISO 14001:2015 – Tsamaiso ea Tikoloho' : lang === 'sw' ? 'ISO 14001:2015 – Usimamizi wa Mazingira' : lang === 'zh' ? 'ISO 14001:2015 – 环境管理' : lang === 'de' ? 'ISO 14001:2015 – Umweltmanagement' : 'ISO 14001:2015 – Environmental Management (Voluntary)', text: this.getComplianceVector('ISO', '14001-2015', lang) },
            { id: 'iso-45001', title: lang === 'zu' ? 'ISO 45001:2018 (Voluntary) – Ukuphathwa Kwe-OHS' : lang === 'xh' ? 'ISO 45001:2018 (Voluntary) – UkuLawulwa kwe-OHS' : lang === 'st' ? 'ISO 45001:2018 (Voluntary) – Tsamaiso ea OHS' : lang === 'sw' ? 'ISO 45001:2018 (Voluntary) – Usimamizi wa OHS' : lang === 'zh' ? 'ISO 45001:2018 (自愿性) – OHS 管理' : lang === 'de' ? 'ISO 45001:2018 (Freiwillig) – Arbeitsschutzmanagement' : 'ISO 45001:2018 (Voluntary) – OHS Management',           text: this.getComplianceVector('ISO', '45001-2018', lang) },
            { id: 'iso-45003', title: lang === 'zu' ? 'ISO 45003:2021 (Voluntary) – Ubungozi Bezengqondo' : lang === 'xh' ? 'ISO 45003:2021 (Voluntary) – Iingozi zeZengqondo' : lang === 'st' ? 'ISO 45003:2021 (Voluntary) – Likotsi tsa Kelello' : lang === 'sw' ? 'ISO 45003:2021 (Voluntary) – Hatari ya Kisaikolojia' : lang === 'zh' ? 'ISO 45003:2021 (自愿性) – 心理社会风险' : lang === 'de' ? 'ISO 45003:2021 (Freiwillig) – Psychosoziales Risiko' : 'ISO 45003:2021 (Voluntary) – Psychosocial Risk',        text: this.getComplianceVector('ISO', '45003-2021', lang) },
        ];
    }

    /** Exported unified payload for Executive Briefings — combines OHS + ISO. */
    public fetchUnifiedBriefing(lang: Language = 'en'): Array<{ id: string; title: string; text: string }> {
        return [
            ...this.fetchOHSBriefing(lang),
            ...this.fetchISOBriefing(lang),
        ];
    }
}

export const GlobalComplianceEngine = new SemanticFirewall();

import { create } from 'zustand';

export type AgentType = 'Nelly' | 'Marcus' | 'Sarah' | 'System' | 'Finance' | 'Training' | 'User';

interface LogEntry {
    id: string;
    agent: AgentType;
    message: string;
    timestamp: string;
}

interface AgentLogState {
    logs: LogEntry[];
    isLowConfidence: boolean;
    addLog: (agent: AgentType, message: string) => void;
    setLowConfidence: (low: boolean) => void;
}

export const useAgentLog = create((set) => ({
    logs: [],
    isLowConfidence: false,
    setLowConfidence: (isLowConfidence) => set({ isLowConfidence }),
    addLog: (agent, message) => set((state) => {
        // Model Armor: Safety Shield for Medical Diagnoses
        const medicalKeywords = ['diagnose', 'diagnosis', 'doctor', 'cure', 'prescription', 'medical advice'];
        const isMedicalQuery = medicalKeywords.some(word => message.toLowerCase().includes(word));

        let finalMessage = message;
        let finalAgent = agent;
        let lowConfidence = state.isLowConfidence;

        if (isMedicalQuery) {
            finalMessage = "HARD-STOP: I am an OHS AI, not a doctor. I cannot provide medical diagnoses. Please consult a professional.";
            finalAgent = 'System';
            lowConfidence = true;
        }

        const newLog = {
            id: Math.random().toString(36).substr(2, 9),
            agent: finalAgent,
            message: finalMessage,
            timestamp: new Date().toLocaleTimeString(),
        };
        return { logs: [newLog, ...state.logs].slice(0, 8), isLowConfidence: lowConfidence };
    }),
}));

import { create } from 'zustand';
import { useTenantStore } from './tenantStore';
import { 
    StatutoryComplianceMetadata, 
    StatutoryRetentionPeriod, 
    StatutoryRecordCategory,
    StatutoryComplianceClassification
} from '../types/statutory';
import { OMP_REFERRAL_STATUTORY_STRING } from '../data/industryPresets';

export type ComplianceStatus = 'COMPLIANT' | 'RISK_ALERT' | 'BREACH' | 'ESCALATED_UNRESOLVED' | 'OVERDUE_HIGH_RISK';
export type EscalationState = 'triggered' | 'routed_to_manager' | 'escalated_level_2' | 'resolved';

export interface EmployeeCase {
    id: string;
    companyId: string;
    employeeName: string;
    dept: string;
    score: number;
    status: ComplianceStatus;
    managerName: string;
    hazardTrigger: string;
    createdAt: string; // ISO string
    timeframeHours: number;
    escalationState: EscalationState;
    statutoryMetadata?: StatutoryComplianceMetadata;
}

export interface ComplianceLog {
    timestamp: string;
    score: number;
    threshold: number;
    reason?: string;
    retentionPeriod?: StatutoryRetentionPeriod;
    retentionCategory?: StatutoryRecordCategory;
    requiresOMPReferral?: boolean;
    ompReferralStatus?: string;
    isStatutoryBreach?: boolean;
}

export interface ComplianceState {
    status: ComplianceStatus;
    requiresEscalation: boolean;
    logs: ComplianceLog[];
    exceptions: string[];
    cases: EmployeeCase[];
    gear: {
        governance: number;
        efficiency: number;
        accountability: number;
        resilience: number;
    };
    demoMode: boolean;
    setDemoMode: (enabled: boolean) => void;
    addWorkspaceException: (exception: string) => void;
    logHazardEvent: (
        type: 'posture' | 'neck_strain' | 'break_interval' | 'physical_hazard' | 'statutory_compliance' | string, 
        description: string, 
        severity?: 'RISK_ALERT' | 'BREACH'
    ) => void;
    evaluateStatutoryPhysicalHazard: (
        hazardType: 'bulk_lift_25kg' | 'carcass_handling' | 'knife_boning' | 'cold_room_stress' | string,
        contextDetails: string,
        employeeName?: string,
        dept?: string
    ) => { triggered: boolean; caseRecord: EmployeeCase };
    logStatutoryLegalBreach: (
        breachType: 'missing_sec16_2' | 'missing_sec17_she_rep' | 'missing_reg6_assessment' | 'refusal_reg10_retention' | 'uncertified_machinery_dmr18',
        details: string,
        responsiblePerson?: string
    ) => EmployeeCase;
    logVerifiedBBSIntervention: (type: string, hazardResolved: string, durationSeconds: number) => void;
    logEmployeeTrainingRecord: (moduleName: string, employeeName: string, competencyVerified: boolean) => void;
    exportStatutoryDocToAuditLog: (docType: string, siteContext: string, previewText: string, reviewerName?: string, reviewerRole?: string) => void;
    triggerBreach: (score: number, threshold: number, timestamp: string, reason?: string) => void;
    resetCompliance: () => void;
    resolveCase: (id: string) => void;
    updateCaseEscalation: (id: string, state: EscalationState) => void;
    tickSimulatedTime: () => void;
    processTelemetry: (data: {
        pelvicSpineAngle: number;
        cervicalSpineTilt: number;
        shoulderElbowAngle: number;
        shoulderElevation: number;
        setupName: string;
    }) => { triggered: boolean; reason: string };
}

/**
 * Deterministic Statutory Evaluation Engine
 * Distinctly separates:
 * 1. Physical Ergonomic & Thermal Hazard Risks:
 *    - Re-classified as "HIGH RISK (Priority Action Required within 7 Days)"
 *    - OMP Referral status: "Assessment indicates ergonomic risk to health: Referral to Occupational Medicine Practitioner (OMP) recommended under Regulation 8(1)"
 *    - Cold room mapped to Regulation 9 of Physical Agents Regulations, 2024 (GN 5952, GG 52226 of 6 March 2025)
 * 2. Statutory Legal Breaches:
 *    - Strictly reserved for explicit legal non-compliance via logStatutoryLegalBreach (NOT keyword matching).
 */
export const detectPhysicalStatutoryHazard = (text: string): { 
    isPhysicalHighRisk: boolean; 
    isStatutoryBreach: boolean;
    hazardLabel: string;
    statutoryMetadata: StatutoryComplianceMetadata 
} => {
    const lower = text.toLowerCase();

    // Strict structured breach detection: ONLY trigger breach for explicit absence/omission phrases
    // NEVER trigger simply because the text mentions "safety representative" or "section 17" (e.g. "reported to safety rep")
    const missingSec17Regex = /\b(?:no|missing|absent|without|lack of|failed to appoint)\s+(?:a\s+)?(?:section\s*17|she|health\s*(?:&|and)\s*safety)\s*(?:rep|representative|designation|appointment)\b|\b(?:section\s*17|she|safety)\s*rep(?:resentative)?\s*(?:is\s+)?(?:absent|missing|not\s+appointed|unappointed)\b/i;
    const isStatutoryBreach = missingSec17Regex.test(lower);

    // Physical Ergonomic & Thermal Hazard Risks (>25kg, carcass handling, knife deboning, cold room stress)
    // Strictly greater than 25 kg from parsed numeric weight. 20kg -> false, 25kg -> false, 26kg -> true.
    const weightMatch = lower.match(/(\d+(?:\.\d+)?)\s*(?:kg|kilos|kilograms)/i);
    const parsedWeight = weightMatch ? parseFloat(weightMatch[1]) : 0;
    const isOver25kgManualHandling = parsedWeight > 25; // Strictly greater than 25 kg

    const isCarcassHandling = lower.includes('carcass') || lower.includes('carcass handling') || lower.includes('beef quarter') || lower.includes('hanging rail');
    const isKnifeDeboning = lower.includes('knife boning') || lower.includes('knife deboning') || lower.includes('deboning') || lower.includes('meat cutting') || lower.includes('band saw') || lower.includes('boning');
    const isColdRoomStress = lower.includes('cold room') || lower.includes('cold-room') || lower.includes('freezer') || lower.includes('chiller') || lower.includes('thermal stress') || lower.includes('sub-zero') || lower.includes('cold stress');

    const isPhysicalHighRisk = isOver25kgManualHandling || isCarcassHandling || isKnifeDeboning || isColdRoomStress;

    let hazardLabel = 'Physical Ergonomic Risk Factor';
    let citation = 'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019) Reg 6, Reg 8(1) & Reg 10(1)';
    let controls = 'Elimination -> Engineering -> Administrative -> PPE';

    if (isOver25kgManualHandling) {
        hazardLabel = 'HIGH RISK: Manual Handling > 25 kg (Priority Action Required within 7 Days)';
        citation = 'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019) Reg 6, Reg 8(1), Reg 8(2) & Reg 10(1); OHS Act Sec 8(2)(b)';
        controls = 'Elimination (pallet automation) -> Engineering (scissor lift / vacuum lifter; inspection logs retained 3 years under Regs 7 & 9) -> Administrative (2-person team lift > 25kg; employee training retained for tenure under Reg 3) -> PPE (lumbar support & steel-toe footwear)';
    } else if (isCarcassHandling) {
        hazardLabel = 'HIGH RISK: Heavy Carcass Handling (Priority Action Required within 7 Days)';
        citation = 'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019) Reg 6, Reg 8(1), Reg 8(2) & Reg 10(1); GSR 13H (Housekeeping & Non-Slip Drainage)';
        controls = 'Engineering (motorized monorail hoists; logs retained 3 years under Regs 7 & 9) -> Administrative (2-butcher team unhooking; training retained for tenure under Reg 3) -> PPE (waterproof boots, chainmail & butcher aprons)';
    } else if (isKnifeDeboning) {
        hazardLabel = 'HIGH RISK: Knife Deboning Force & Tendon Strain (Priority Action Required within 7 Days)';
        citation = 'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019) Reg 6, Reg 8(1), Reg 8(2) & Reg 10(1); COIDA Schedule 3';
        controls = 'Engineering (ergonomic non-slip knife handles, motorized hollow grinders) -> Administrative (30-min task rotation) -> PPE (chainmail cut-resistant gloves)';
    } else if (isColdRoomStress) {
        hazardLabel = 'HIGH RISK: Cold Room Thermal Stress (Priority Action Required within 7 Days)';
        citation = 'Physical Agents Regulations, 2024 (GN 5952, GG 52226 of 6 March 2025) Regulation 9 (Cold Stress) (Repealing ERW 1987); Ergonomics Regulations, 2019 (GN R1589) Reg 8(1), Reg 8(2) & Reg 10(1); GSR 13J';
        controls = 'Engineering (heated door gaskets, emergency door push-bars complying with GSR 13J) -> Administrative (max 45 min cold exposure under Reg 9, hot drink warmup breaks) -> PPE (thermal freezer suits, insulated balaclavas)';
    }

    if (isStatutoryBreach) {
        hazardLabel = 'STATUTORY BREACH: Absence of Section 17 Health & Safety Representative Designation';
        citation = 'OHS Act 85 of 1993 Section 17';
        controls = 'Mandatory designation in writing of accredited Health & Safety Representative under Section 17(1)';
    }

    return {
        isPhysicalHighRisk,
        isStatutoryBreach,
        hazardLabel,
        statutoryMetadata: {
            retentionPeriod: 40,
            retentionCategory: 'REG_8_2_MEDICAL_SURVEILLANCE_RECORD_40_YR',
            retentionDescription: 'Medical surveillance records retained 40 years under Ergonomics Regulations, 2019 Regulation 10(1)',
            isStatutoryBreach,
            requiresOMPReferral: isPhysicalHighRisk,
            ompReferralStatus: isPhysicalHighRisk ? OMP_REFERRAL_STATUTORY_STRING : undefined,
            statutoryCitation: citation,
            hierarchyOfControlsMandate: controls,
            competentPersonRequirement: 'Appointed Risk Assessor & Registered Occupational Medicine Practitioner (OMP)',
            riskClassification: 'HIGH_RISK_PRIORITY_ACTION',
            statutoryNotice: 'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019) & Physical Agents Regulations, 2024 (GN 5952, GG 52226 of 6 March 2025)'
        }
    };
};

