});

import { test, expect } from '@playwright/test';
import { 
    useComplianceStore, 
    detectPhysicalStatutoryHazard 
} from '../src/store/complianceStore';
import { 
    PHYSICAL_AGENTS_REGS_2024_CITATION, 
    ERGONOMICS_REGS_2019_CITATION,
    REPEALED_ENVIRONMENTAL_REGS_1987,
    OMP_REFERRAL_STATUTORY_STRING 
} from '../src/types/statutory';
import { 
    wholesaleCashCarryPreset, 
    retailButcheryPreset 
} from '../src/data/industryPresets';

test.describe('Compliance Store & Statutory Scoring Engine Unit Tests', () => {
    test.beforeEach(() => {
        useComplianceStore.getState().resetCompliance();
        useComplianceStore.setState({ demoMode: false });
    });

    test('1. Legal Citations & Repeal of ERW 1987', () => {
        expect(PHYSICAL_AGENTS_REGS_2024_CITATION).toBe(
            'Physical Agents Regulations, 2024 (GN 5952, GG 52226 of 6 March 2025)'
        );
        expect(ERGONOMICS_REGS_2019_CITATION).toBe(
            'Ergonomics Regulations, 2019 (GN R1589, GG 42894 of 6 December 2019)'
        );
        expect(REPEALED_ENVIRONMENTAL_REGS_1987).toContain('Repealed by Physical Agents Regulations, 2024');
    });

    test('2. 26 kg lift triggers HIGH RISK, NOT BREACH', () => {
        // Direct detection helper evaluation
        const detection = detectPhysicalStatutoryHazard('Manual handling of 26 kg heavy meat box on loading bay');

        expect(detection.isPhysicalHighRisk).toBe(true);
        expect(detection.isStatutoryBreach).toBe(false);
        expect(detection.statutoryMetadata.riskClassification).toBe('HIGH_RISK_PRIORITY_ACTION');
        expect(detection.hazardLabel).toContain('HIGH RISK');
        expect(detection.hazardLabel).not.toContain('BREACH');
        expect(detection.statutoryMetadata.requiresOMPReferral).toBe(true);
        expect(detection.statutoryMetadata.ompReferralStatus).toBe(OMP_REFERRAL_STATUTORY_STRING);

        // Store state evaluation
        const store = useComplianceStore.getState();
        const result = store.evaluateStatutoryPhysicalHazard(
            'bulk_lift_25kg',
            'Worker lifted 26 kg box of frozen lamb shoulders',
            'Sipho Dlamini',
            'Cold Storage'
        );

        expect(result.triggered).toBe(true);
        expect(result.caseRecord.status).toBe('RISK_ALERT'); // High risk alert, NOT BREACH
        expect(result.caseRecord.status).not.toBe('BREACH');
        expect(result.caseRecord.score).toBe(30);
        expect(result.caseRecord.statutoryMetadata?.riskClassification).toBe('HIGH_RISK_PRIORITY_ACTION');
        expect(result.caseRecord.hazardTrigger).toContain('HIGH RISK (Priority Action Required within 7 Days)');
    });

    test('3. Training records default to employee tenure retention (Regulation 10(1))', () => {
        const store = useComplianceStore.getState();
        store.logEmployeeTrainingRecord(
            'Safe Lifting & Manual Handling Techniques (Reg 3)',
            'Themba Nkosi',
            true
        );

        const updatedCases = useComplianceStore.getState().cases;
        const trainingCase = updatedCases.find(c => c.employeeName === 'Themba Nkosi');

        expect(trainingCase).toBeDefined();
        expect(trainingCase?.statutoryMetadata?.retentionPeriod).toBe('TENURE');
        expect(trainingCase?.statutoryMetadata?.retentionCategory).toBe('REG_3_EMPLOYEE_TRAINING_RECORD_TENURE');
        expect(trainingCase?.status).toBe('COMPLIANT');
    });

    test('4. Assessment and surveillance records enforce 40-year statutory retention', () => {
        const store = useComplianceStore.getState();

        // Surveillance record from physical hazard evaluation
        const evalResult = store.evaluateStatutoryPhysicalHazard(
            'carcass_handling',
            'Butcher handling 65 kg beef side on hanging rail',
            'Johan van der Merwe',
            'Meat Processing'
        );

        expect(evalResult.caseRecord.statutoryMetadata?.retentionPeriod).toBe(40);
        expect(evalResult.caseRecord.statutoryMetadata?.retentionCategory).toBe('REG_8_2_MEDICAL_SURVEILLANCE_RECORD_40_YR');

        // Risk log retention check
        const logs = useComplianceStore.getState().logs;
        const latestLog = logs[0];
        expect(latestLog.retentionPeriod).toBe(40);
        expect(latestLog.retentionCategory).toBe('REG_8_2_MEDICAL_SURVEILLANCE_RECORD_40_YR');
        expect(latestLog.ompReferralStatus).toBe(OMP_REFERRAL_STATUTORY_STRING);
    });

    test('5. Genuine statutory non-compliance strictly triggers BREACH', () => {
        const store = useComplianceStore.getState();

        const breachCase = store.logStatutoryLegalBreach(
            'missing_sec16_2',
            'Audit revealed no written Section 16(2) delegation exists for the branch manager',
            'Managing Director'
        );

        expect(breachCase.status).toBe('BREACH');
        expect(breachCase.statutoryMetadata?.isStatutoryBreach).toBe(true);
        expect(breachCase.statutoryMetadata?.riskClassification).toBe('STATUTORY_BREACH');
        expect(breachCase.hazardTrigger).toContain('[STATUTORY BREACH]');
        expect(breachCase.statutoryMetadata?.retentionPeriod).toBe(40);
    });

    test('6. Cold room stress maps to Regulation 9 of Physical Agents Regulations, 2024', () => {
        const detection = detectPhysicalStatutoryHazard('Worker exposed to -18C cold room freezer without thermal recovery intervals');

        expect(detection.isPhysicalHighRisk).toBe(true);
        expect(detection.statutoryMetadata.statutoryCitation).toContain('Physical Agents Regulations, 2024 (GN 5952, GG 52226 of 6 March 2025) Regulation 9 (Cold Stress)');
        expect(detection.statutoryMetadata.statutoryCitation).toContain('Repealing ERW 1987');
        expect(detection.statutoryMetadata.requiresOMPReferral).toBe(true);
    });

    test('7. Industry Presets: Wholesale Cash & Carry and Retail Butchery validation', () => {
        // Wholesale Cash & Carry
        expect(wholesaleCashCarryPreset.industryName).toBe('Wholesale Cash & Carry');
        expect(wholesaleCashCarryPreset.shiftConstraints.maxSingleManualLiftKg).toBe(25);
        expect(wholesaleCashCarryPreset.retentionPolicies.reg6RiskAssessmentsYears).toBe(40);
        expect(wholesaleCashCarryPreset.retentionPolicies.reg8_2MedicalSurveillanceYears).toBe(40);
        expect(wholesaleCashCarryPreset.retentionPolicies.reg7And9EquipmentInspectionYears).toBe(3);
        expect(wholesaleCashCarryPreset.retentionPolicies.reg3EmployeeTraining).toBe('TENURE');

        // Retail Butchery
        expect(retailButcheryPreset.industryName).toBe('Retail Butchery & Meat Processing');
        expect(retailButcheryPreset.shiftConstraints.physicalAgentsReg9ColdExposureLimitMinutes).toBe(45);
        expect(retailButcheryPreset.primaryPhysicalHazards.some((h: any) => h.category === 'PHYSICAL_CARCASS_HANDLING')).toBe(true);
        expect(retailButcheryPreset.primaryPhysicalHazards.some((h: any) => h.category === 'PHYSICAL_KNIFE_DEBONING')).toBe(true);
        expect(retailButcheryPreset.primaryPhysicalHazards.some((h: any) => h.category === 'PHYSICAL_COLD_ROOM_STRESS_REG_9')).toBe(true);
    });

    test('8. Full 3-Tier Retention Schedule Verification', () => {
        const policies = wholesaleCashCarryPreset.retentionPolicies;

        // Tier 1: 40 Years
        expect(policies.reg6RiskAssessmentsYears).toBe(40);
        expect(policies.reg8_2MedicalSurveillanceYears).toBe(40);

        // Tier 2: 3 Years
        expect(policies.reg7And9EquipmentInspectionYears).toBe(3);
        expect(policies.gsr13FacilitiesYears).toBe(3);

        // Tier 3: Tenure (Duration of employment)
        expect(policies.reg3EmployeeTraining).toBe('TENURE');
    });
});

import { test, expect } from '@playwright/test';

test.describe('ErgoSafe Reborn V3 14-Route Core Verification Pass', () => {

    test('All 14 Core Navigation Routes Mount Cleanly with 0 Console Errors', async ({ page }) => {
        const consoleErrors: string[] = [];
        page.on('console', msg => {
            if (msg.type() === 'error') {
                consoleErrors.push(msg.text());
            }
        });

        // Load Application Root
        await page.goto('/');
        await page.waitForLoadState('networkidle');
        await expect(page.locator('body')).toBeVisible();

        const routes = [
            { name: 'Stewardship Overview', expected: /Executive Briefing|Stewardship/i },
            { name: 'Nelly Posture & Hazard Monitoring Engine (3D Spine)', expected: /Hazard Engine|Nelly Posture/i },
            { name: 'Ground-Zero Human Co-Pilot Companion', expected: /Human Co-Pilot|Companion/i },
            { name: 'Prizm Driver & Shift Fatigue Telemetry', expected: /Driver & Shift|Prizm/i },
            { name: 'Ergonomics Cognitive Handshake', expected: /Cognitive Handshake|Dot-Click/i },
            { name: 'Smart Break & Mobility Engine', expected: /Smart Break|Mobility Engine/i },
            { name: 'Organic SOP & ISO 45001 Generator', expected: /Organic SOP|ISO 45001/i },
            { name: 'Ergonomics Training & Certification', expected: /Curriculum|Enterprise OHS/i },
            { name: 'Daily Self-Risk Assessment (WFH / Desk)', expected: /Self-Risk|Assessment/i },
            { name: 'Daily Workstation Safety Checklist', expected: /Checklist|Safety/i },
            { name: 'HR & Compliance Dashboard', expected: /OHS Compliance|Escalation/i },
            { name: 'Risky Behaviours Monitoring', expected: /Risky Behaviours|Habits/i },
            { name: 'Assessment PDF Invoices & Billing', expected: /Invoicing|Financial/i },
            { name: 'Analytics & Regulatory Audit Logs', expected: /Analytics & Regulatory|Audit/i },
        ];

        for (const route of routes) {
            // Open sidebar drawer prior to asserting navigation links if hidden
            const btn = page.locator(`button:has-text("${route.name}")`).first();
            if (!(await btn.isVisible().catch(() => false))) {
                const toggleSidebarBtn = page.getByRole('button', { name: /Toggle Sidebar/i }).first();
                if (await toggleSidebarBtn.isVisible().catch(() => false)) {
                    await toggleSidebarBtn.click();
                    await page.waitForTimeout(300);
                }
            }

            if (await btn.isVisible().catch(() => false)) {
                await btn.scrollIntoViewIfNeeded();
                await btn.evaluate((el: HTMLElement) => el.click());
                await page.waitForTimeout(400);
                await expect(page.locator('body')).toContainText(route.expected, { timeout: 7000 });
            }
        }

        expect(consoleErrors.length).toBe(0);
    });
});

import { test, expect } from '@playwright/test';

test.describe('PHASE 0 UI: Consent & Emergency UI Verification', () => {

    test('0.3 Fresh load with empty localStorage -> consent key is absent until accept clicked', async ({ page }) => {
        // Clear storage
        await page.goto('/');
        await page.evaluate(() => {
            localStorage.clear();
        });

        await page.reload();
        await page.waitForLoadState('networkidle');

        // Verify ergo_privacy_consent_verified is absent on fresh load
        const consentBefore = await page.evaluate(() => localStorage.getItem('ergo_privacy_consent_verified'));
        expect(consentBefore).toBeNull();

        // Privacy handshake modal should appear
        const acceptBtn = page.getByRole('button', { name: /ACCEPT PRIVACY HANDSHAKE/i });
        if (await acceptBtn.isVisible({ timeout: 4000 }).catch(() => false)) {
            await acceptBtn.click();
            await page.waitForTimeout(300);

            // After click, consent key is now present
            const consentAfter = await page.evaluate(() => localStorage.getItem('ergo_privacy_consent_verified'));
            expect(consentAfter).toBe('true');
        }
    });

    test('0.1 Emergency UI never renders personal cellphone 27622655708 and renders tel:112', async ({ page }) => {
        await page.goto('/');
        await page.waitForLoadState('networkidle');

        // Check page content does not contain personal cellphone number
        const pageText = await page.textContent('body');
        expect(pageText).not.toContain('27622655708');
        expect(pageText).not.toContain('+27 62 265 5708');
    });
});

import { test, expect } from '@playwright/test';
import { useComplianceStore, detectPhysicalStatutoryHazard } from '../src/store/complianceStore';
import { useFatigueStore } from '../src/logic/Fatigue-Check/fatigueStore';
import { useTenantStore, SA_PUBLIC_EMERGENCY_CONTACTS } from '../src/store/tenantStore';

test.describe('PHASE 0: Life-Safety & Correctness Verification Suite', () => {

    test.beforeEach(() => {
        useComplianceStore.getState().resetCompliance();
        useComplianceStore.setState({ demoMode: false });
        useFatigueStore.getState().supervisorOverride();
    });

    test('0.1 Emergency UI never renders personal cellphone and defaults to SA emergency numbers', () => {
        const tenant = useTenantStore.getState().getCurrentTenant();
        const contacts = tenant?.emergencyContacts || SA_PUBLIC_EMERGENCY_CONTACTS;

        // Assert public emergency numbers are present
        const numbers = contacts.map(c => c.number);
        expect(numbers).toContain('112');
        expect(numbers).toContain('10177');
        expect(numbers).toContain('10111');

        // Assert personal cellphone is never in emergency contacts
        expect(numbers).not.toContain('+27622655708');
        expect(numbers).not.toContain('27622655708');

        // Assembly point fallback
        expect(tenant?.assemblyPoint).toBe('Follow your site evacuation plan');
    });

    test('0.2 Fatigue Store: failCognitiveHandshake leaves cognitiveHandshakePassed === false', () => {
        const fatigue = useFatigueStore.getState();
        fatigue.failCognitiveHandshake();

        const updated = useFatigueStore.getState();
        expect(updated.cognitiveHandshakePassed).toBe(false);
        expect(updated.fatigueLevel).toBe('high');
        expect(updated.status).toBe('HIGH');
        expect(updated.locked).toBe(true);

        // warnCognitiveHandshake test: must NOT set cognitiveHandshakePassed to true
        fatigue.warnCognitiveHandshake();
        const warned = useFatigueStore.getState();
        expect(warned.cognitiveHandshakePassed).toBe(false);
        expect(warned.fatigueLevel).toBe('warning');
        expect(warned.status).toBe('WARNING');
    });

    test('0.4 Simulated clock does not touch real records with demoMode: false, and past SLA keeps RISK_ALERT', () => {
        const store = useComplianceStore.getState();
        store.setDemoMode(false);

        // Evaluate physical hazard (72h SLA)
        const result = store.evaluateStatutoryPhysicalHazard(
            'bulk_lift_25kg',
            'Worker lifted 28 kg carton',
            'Floor Worker',
            'Logistics'
        );

        const caseId = result.caseRecord.id;
        expect(result.caseRecord.status).toBe('RISK_ALERT');
        expect(result.caseRecord.escalationState).toBe('routed_to_manager');

        // Tick simulated time under demoMode: false (5 real seconds = ~0.0014 hours)
        store.tickSimulatedTime();
        const caseAfterTick = useComplianceStore.getState().cases.find(c => c.id === caseId);
        expect(caseAfterTick?.escalationState).toBe('routed_to_manager'); // Should not escalate after 5 seconds
        expect(caseAfterTick?.status).toBe('RISK_ALERT');

        // Explicitly escalate past SLA to escalated_level_2: MUST NOT change status to BREACH
        store.updateCaseEscalation(caseId, 'escalated_level_2');
        const escalatedCase = useComplianceStore.getState().cases.find(c => c.id === caseId);
        expect(escalatedCase?.escalationState).toBe('escalated_level_2');
        expect(escalatedCase?.status).toBe('OVERDUE_HIGH_RISK'); // Physical hazard escalates to OVERDUE_HIGH_RISK, not BREACH
        expect(escalatedCase?.status).not.toBe('BREACH');
    });

    test('0.5 Hazard detection false positives (strict >25kg numeric and no free-text legal breaches)', () => {
        // 1. "reported to the safety representative" -> not a breach
        const repCheck = detectPhysicalStatutoryHazard('Incident reported to the safety representative for review');
        expect(repCheck.isStatutoryBreach).toBe(false);
        expect(repCheck.isPhysicalHighRisk).toBe(false);

        // 2. "20 kg box" -> not HIGH RISK
        const underWeight = detectPhysicalStatutoryHazard('Worker lifted a 20 kg box of produce');
        expect(underWeight.isPhysicalHighRisk).toBe(false);
        expect(underWeight.isStatutoryBreach).toBe(false);

        // 3. "exactly 25 kg" -> not HIGH RISK (strictly greater than 25 kg required)
        const exactWeight = detectPhysicalStatutoryHazard('Worker lifted exactly 25 kg parcel');
        expect(exactWeight.isPhysicalHighRisk).toBe(false);
        expect(exactWeight.isStatutoryBreach).toBe(false);

        // 4. "26 kg box" -> HIGH RISK, not BREACH
        const overWeight = detectPhysicalStatutoryHazard('Worker lifted a 26 kg box on loading bay');
        expect(overWeight.isPhysicalHighRisk).toBe(true);
        expect(overWeight.isStatutoryBreach).toBe(false);
        expect(overWeight.hazardLabel).toContain('HIGH RISK');
        expect(overWeight.hazardLabel).not.toContain('BREACH');

        // 5. "a 5 kg meat box" -> not >25 kg HIGH RISK
        const smallMeatBox = detectPhysicalStatutoryHazard('Worker carrying a 5 kg meat box to display counter');
        expect(smallMeatBox.isPhysicalHighRisk).toBe(false);
        expect(smallMeatBox.isStatutoryBreach).toBe(false);
    });
});

import { defineConfig, Plugin } from 'vite';
import react from '@vitejs/plugin-react';
import { generateStatutoryDocument } from './src/api/compliance';

function apiDevMiddleware(): Plugin {
  return {
    name: 'api-dev-middleware',
    configureServer(server) {
      server.middlewares.use(async (req, res, next) => {
        if (req.url === '/api/compliance') {
          // Check Bearer auth
          const authHeader = req.headers['authorization'] || req.headers['Authorization'];
          const token = typeof authHeader === 'string' && authHeader.startsWith('Bearer ')
            ? authHeader.slice(7).trim()
            : null;
          const expectedToken = process.env.ERGOSAFE_API_TOKEN || 'ergosafe-dev-token';

          if (!token || token !== expectedToken) {
            res.statusCode = 401;
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({ error: 'Unauthorized: missing or invalid Bearer token' }));
            return;
          }

          if (req.method === 'GET') {
            res.statusCode = 200;
            res.setHeader('Content-Type', 'application/json');
            res.end(JSON.stringify({
              service: 'ErgoSafe Statutory OHS Compliance Engine',
              endpoint: '/api/compliance',
              status: 'OPERATIONAL',
              framework: 'South African OHS Act 85 of 1993 & Ergonomics Regs 2019',
              version: 'v3.0.0',
              timestamp: new Date().toISOString()
            }));
            return;
          }

          if (req.method === 'POST') {
            let body = '';
            req.on('data', chunk => {
              body += chunk;
            });
            req.on('end', async () => {
              try {
                const payload = body ? JSON.parse(body) : {};
                const VALID_TASK_TYPES = ['HIRA', 'SWP', 'Incident Root Cause', 'Toolbox Talk'];

                if (!payload.taskType || !VALID_TASK_TYPES.includes(payload.taskType)) {
                  res.statusCode = 400;
                  res.setHeader('Content-Type', 'application/json');
                  res.end(JSON.stringify({
                    error: `Bad Request: taskType must be one of [${VALID_TASK_TYPES.join(', ')}]`
                  }));
                  return;
                }

                if (payload.siteContext && typeof payload.siteContext === 'string' && payload.siteContext.length > 200) {
                  res.statusCode = 400;
                  res.setHeader('Content-Type', 'application/json');
                  res.end(JSON.stringify({
                    error: 'Bad Request: siteContext exceeds maximum allowed length of 200 characters'
                  }));
                  return;
                }

                if (payload.hazards && typeof payload.hazards === 'string' && payload.hazards.length > 2000) {
                  res.statusCode = 400;
                  res.setHeader('Content-Type', 'application/json');
                  res.end(JSON.stringify({
                    error: 'Bad Request: hazards exceeds maximum allowed length of 2000 characters'
                  }));
                  return;
                }

                const result = await generateStatutoryDocument(payload);
                if (!result.success && result.error && result.error.includes('Service Unavailable')) {
                  res.statusCode = 503;
                  res.setHeader('Content-Type', 'application/json');
                  res.end(JSON.stringify({ success: false, error: 'Service Unavailable: upstream AI compliance model is currently unavailable' }));
                  return;
                }
                res.statusCode = 200;
                res.setHeader('Content-Type', 'application/json');
                res.end(JSON.stringify(result));
              } catch (err: any) {
                res.statusCode = 500;
                res.setHeader('Content-Type', 'application/json');
                res.end(JSON.stringify({ success: false, error: err.message }));
              }
            });
            return;
          }
        }

        next();
      });
    }
  };
}

// https://vitejs.dev/config/
export default defineConfig({
  base: '/',
  plugins: [react(), apiDevMiddleware()],
  build: {
    reportCompressedSize: false,
    chunkSizeWarningLimit: 900,
    rollupOptions: {
      output: {
        manualChunks: {
          'vendor-three': ['three', '@react-three/fiber', '@react-three/drei'],
          'vendor-ui': ['lucide-react', 'framer-motion'],
          'vendor-core': ['react', 'react-dom', 'zustand']
        }
      }
